// RECEIVING — normalize inbound chat from the Atlas /chat surface.
const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const prompt = body.prompt ?? body.message ?? body.text ?? '';
const history = body.history ?? [];
const idempotency_key = headers['idempotency-key'] || body.idempotency_key || $execution.id || (''+Date.now());
const authorization = body.authorization ?? headers['x-owner-authorization'] ?? '';
const cockpitBase = $env.MUSE_COCKPIT_URL || 'http://host.docker.internal:8765';
const connectorBase = $env.MUSE_N8N_BASE || 'http://localhost:5678';
return [{ json: { phase:'RECEIVING', prompt, history, idempotency_key, authorization,
  session_key: body.session_key ?? null, cockpitBase, connectorBase,
  received_at: new Date().toISOString() } }];

// Parse the NDJSON turn stream and fold the wire vocabulary into a summary.
const inItem = $input.first().json;
const raw = inItem.data ?? inItem.body ?? inItem ?? '';
const text = (typeof raw === 'string') ? raw : JSON.stringify(raw);
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
let speak='', ownerReq=false, done=false, err=null;
const phases=[], details=[], evidenceRefs=[], ledgerRefs=[], approvals=[];
for (const line of lines){ let c; try{ c=JSON.parse(line); }catch(e){ continue; }
  switch(c.type){
    case 'phase': phases.push(c.phase ?? c.value); break;
    case 'body': speak = c.text ?? c.value ?? speak; break;
    case 'body_delta': speak += (c.text ?? c.value ?? ''); break;
    case 'detail': { const d=c.text ?? c.value ?? ''; details.push(d);
        if(/owner approval required/i.test(d)) ownerReq=true; break; }
    case 'approval': approvals.push(c); ownerReq=true; break;
    case 'evidence': evidenceRefs.push(c.id ?? c.ref ?? c.value); break;
    case 'ledger': ledgerRefs.push(c.id ?? c.ref ?? c.value); break;
    case 'done': done=true; break;
    case 'error': err = c.error ?? c.message ?? c.value ?? 'error'; break;
  } }
const ctx = $('RECEIVING - normalize').first().json;
return [{ json: { ...ctx, phase:'PARSED', speak, phases, details, evidenceRefs, ledgerRefs,
  owner_approval_required: ownerReq, approvals, done, error: err, raw_chunk_count: lines.length } }];

// Atlas read-back — mirror each internal stage by reading the live cockpit surfaces.
const ctx = $input.first().json;
const base = ctx.cockpitBase || ($env.MUSE_COCKPIT_URL || 'http://host.docker.internal:8765');
const token = $env.MUSE_COCKPIT_TOKEN || '';
const H = { Authorization: 'Bearer ' + token };
const self = this;
async function get(path){
  try { return await self.helpers.httpRequest({ method:'GET', url: base+path, headers:H, json:true, timeout:8000 }); }
  catch(e){ return { _error: String(e).slice(0,200), _path: path }; }
}
const [axiom, ledger, memory, evidence, autonomy, approvals] = await Promise.all([
  get('/v1/cockpit/axiom'), get('/v1/cockpit/ledger'), get('/v1/cockpit/memory/tree'),
  get('/v1/cockpit/evidence'), get('/v1/cockpit/autonomy'), get('/v1/cockpit/approvals') ]);
const chain_valid = (axiom && axiom.audit) ? axiom.audit.chain_valid : null;
const ledger_latest_hash = (axiom && axiom.audit) ? (axiom.audit.tip ?? null) : null;
return [{ json: { ...ctx, atlas: { axiom, ledger, memory, evidence, autonomy, approvals },
  chain_valid, ledger_latest_hash } }];

// Gate mirror — surface all 8 verification gates with authoritative signals.
// Real gating ran server-side; chain_valid comes from GET /v1/cockpit/axiom.
// Risk->profile mirrors GATE_PROFILES (hermes_cli/jarvis_prime/axiom_bridge.py).
const ctx = $input.first().json;
const t = (ctx.prompt || '').toLowerCase();
let risk='LOW';
if(/(deploy|publish|release|push|dns|secret|credential|oauth|spend|pay|charge|package|app store|production)/.test(t)) risk='HIGH';
else if(/(edit|refactor|write|change|migrate|install|build|fix|implement|create|update)/.test(t)) risk='MED';
const ALL=['planning','build','review','test','security','release','owner_approval','rollback'];
const PROFILE={ LOW:['build','test'],
  MED:['planning','build','review','test','security','rollback'], HIGH: ALL };
const active=PROFILE[risk];
const cv=ctx.chain_valid;
const ownerReq=!!ctx.owner_approval_required || risk==='HIGH';
const gates=ALL.map(name=>{ let outcome=active.includes(name)?'pass':'skipped';
  if(name==='owner_approval'&&active.includes(name)) outcome=ownerReq?'needs_owner_approval':'pass';
  if(name==='release'&&active.includes(name)&&cv===false) outcome='fail';
  return { gate:name, outcome, active:active.includes(name) }; });
const all_gates_pass=gates.every(g=>g.outcome!=='fail');
const needs_owner_approval=gates.some(g=>g.outcome==='needs_owner_approval')||ownerReq;
return [{ json: { ...ctx, risk, gate_profile:active, gates, all_gates_pass, needs_owner_approval } }];

// Mirror JarvisPrime.delegate() envelope (runtime.py) and map action -> connector path.
const ctx = $input.first().json;
const p = (ctx.prompt||'').toLowerCase();
let connector='generic', action='delegate';
if(/email|gmail|inbox/.test(p)){ connector='gmail-send'; action='send_email'; }
else if(/slack|channel|dm|message|notify|post/.test(p)){ connector='slack-post'; action='post_message'; }
const envelope = { target:'n8n', delegate_to:connector, action,
  rationale:'AXIOM-gated action delegated to the n8n connector layer',
  packet_id: ctx.idempotency_key, idempotency_key: ctx.idempotency_key,
  verified_by: ctx.ledger_latest_hash || 'axiom-tip-unavailable',
  requires_owner_authorization: !!ctx.needs_owner_approval,
  ledger_latest_hash: ctx.ledger_latest_hash || null,
  payload: { prompt: ctx.prompt, speak: ctx.speak },
  connector_path: 'muse-connector-' + connector };
return [{ json: { ...ctx, envelope, connector_path: envelope.connector_path } }];

// GuardrailLedger-shaped record. The hash-chained append is HOST-SIDE
// (GuardrailLedger.append -> $HERMES_HOME/jarvis_prime/guardrail_ledger.jsonl, 0600, O_APPEND).
// n8n cannot write the host chain; it emits the record for the host dispatcher.
const ctx = $('Build delegation envelope').first().json;
const resp = $input.first().json;
const record = { event:'n8n_delegation', kind:'n8n_delegation', subject: ctx.connector_path,
  payload: { webhook_path: ctx.connector_path, idempotency_key: ctx.idempotency_key,
    verified_by: ctx.envelope ? ctx.envelope.verified_by : null,
    ok: !(resp && resp._error), connector_response: resp } };
return [{ json: { ...ctx, delegation_result: resp, ledger_record: record } }];

// SPEAK — assemble the final envelope for the Atlas /chat surface.
function safe(fn,d){ try{ return fn(); }catch(e){ return d; } }
const base = $input.first().json;
const gm = safe(()=>$('Gate mirror (8 gates)').first().json, {});
const del = safe(()=>$('Delegation ledger record').first().json, null);
const out = { phase:'FINAL', speak: base.speak ?? gm.speak ?? '',
  turn: { risk: gm.risk, phases: gm.phases, done: gm.done, error: gm.error },
  gates: gm.gates, all_gates_pass: gm.all_gates_pass,
  owner_approval_required: gm.needs_owner_approval ?? base.owner_approval_required,
  delegation: del ? del.delegation_result : null,
  ledger_record: del ? del.ledger_record : null,
  evidence_refs: gm.evidenceRefs ?? base.evidenceRefs ?? [],
  ledger_refs: gm.ledgerRefs ?? base.ledgerRefs ?? [],
  chain_valid: gm.chain_valid ?? base.chain_valid ?? null,
  idempotency_key: base.idempotency_key ?? gm.idempotency_key,
  atlas_station:'/chat (Atlas Crown · Neural Conversation)', done:true };
return [{ json: out }];
